contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "0", "0"); }
    function testFuzz_property(address caller, uint256 burnAmount) public {
        // Bound burnAmount to something that can actually be burned.
        // The owner is the deployer of setUp, which is this contract.
        // We need actual tokens for the caller if that caller is to burn.
        // We set up a scenario where the caller calls owned() to potentially change owner,
        // then attempts to burn. We measure owner before and after the burn attempt.
        // Pristine owner before any calls is address(this).
        address origOwner = c.owner();

        // Give the contract some tokens to burn by minting to this contract (as owner).
        vm.prank(origOwner);
        c.mintToken(address(this), 1000);

        // Give caller some tokens to burn if caller != address(this)
        if (caller != address(this)) {
            vm.prank(origOwner);
            c.mintToken(caller, 1000);
        }

        // Bound burnAmount to available balance.
        uint256 bal = c.balanceOf(address(this));
        burnAmount = bound(burnAmount, 1, bal);

        // Prank the caller
        vm.startPrank(caller);
        // Call owned() which in the mutant changes owner to tx.origin (caller),
        // or in reference does nothing because onlyOwner reverts (caller is not owner yet).
        try c.owned() {} catch {}
        // Now attempt to burn
        bool burnOk;
        try c.burn(burnAmount) { burnOk = true; } catch { burnOk = false; }
        vm.stopPrank();

        // After these operations, if burn succeeded, the owner should still be origOwner.
        // In the reference, owned() reverts (caller is not owner), so burn reverts.
        // In the mutant, owned() succeeds and sets owner to caller (tx.origin), then burn succeeds as owner,
        // leaving owner changed. If burn fails in either, owner should also remain unchanged.
        // The property: a successful burn by a caller that initially is not owner must not change the owner.
        if (burnOk) {
            assertTrue(c.owner() == origOwner);
        } else {
            // If burn failed, owner must also be unchanged.
            assertTrue(c.owner() == origOwner);
        }
    }
}

